<script>
const cvs = document.getElementById('gauge'), gctx = cvs.getContext('2d');
function drawProgress(percent) {
    gctx.clearRect(0, 0, 160, 160);
    const cx = 80, cy = 80, r = 60;
    // Track
    gctx.beginPath();
    gctx.arc(cx, cy, r, 0, Math.PI * 2);
    gctx.strokeStyle = '#222';
    gctx.lineWidth = 10;
    gctx.stroke();
    // Fill
    gctx.beginPath();
    gctx.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * (percent / 100)));
    gctx.strokeStyle = '#10b981';
    gctx.lineWidth = 10;
    gctx.lineCap = 'round';
    gctx.stroke();
    // Text
    gctx.fillStyle = '#fff';
    gctx.font = 'bold 20px sans-serif';
    gctx.textAlign = 'center';
    gctx.textBaseline = 'middle';
    gctx.fillText(percent + '%', cx, cy);
}
drawProgress(85);
</script>
```

```html
<canvas id="waveCanvas" width="500" height="200" style="background:#0b0f19;"></canvas>
<script>
const c = document.getElementById('waveCanvas'), ctx = c.getContext('2d');
let t = 0;
function animate() {
    ctx.fillStyle = 'rgba(11, 15, 25, 0.2)';
    ctx.fillRect(0, 0, c.width, c.height);
    ctx.beginPath();
    ctx.strokeStyle = '#00f2fe';
    ctx.lineWidth = 2;
    for(let x = 0; x < c.width; x++) {
        const y = 100 + Math.sin(x * 0.03 + t) * 40 * Math.sin(t * 0.5);
        if(x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    t += 0.05;
    requestAnimationFrame(animate);
}
animate();
</script>
```

