```html
<canvas id="candleCanvas" width="600" height="300" style="background:#141722; border-radius:8px;"></canvas>
<script>
const canvas = document.getElementById('candleCanvas');
const ctx = canvas.getContext('2d');
const candles = [
    { o: 150.2, h: 150.8, l: 150.1, c: 150.6 },
    { o: 150.6, h: 150.9, l: 150.3, c: 150.4 },
    { o: 150.4, h: 151.2, l: 150.2, c: 151.0 },
    { o: 151.0, h: 151.4, l: 150.7, c: 151.3 },
    { o: 151.3, h: 151.5, l: 150.9, c: 150.8 }
];

function drawCandles() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const minP = 150.0, maxP = 151.6;
    const toY = p => canvas.height - ((p - minP) / (maxP - minP)) * (canvas.height - 40) - 20;

    candles.forEach((c, i) => {
        const x = 50 + i * 80;
        const isBull = c.c >= c.o;
        ctx.strokeStyle = isBull ? '#089981' : '#f23645';
        ctx.fillStyle = ctx.strokeStyle;

        // Wick
        ctx.beginPath();
        ctx.moveTo(x, toY(c.h));
        ctx.lineTo(x, toY(c.l));
        ctx.stroke();

        // Body
        const yTop = toY(Math.max(c.o, c.c));
        const bodyH = Math.max(2, Math.abs(toY(c.o) - toY(c.c)));
        ctx.fillRect(x - 14, yTop, 28, bodyH);
    });
}
drawCandles();
</script>
```

